// Integrate independently self-reviewed, exclusive owner packets; no cross-lane semantic review.
const fs=require('fs'),cp=require('child_process'),z=require('zlib'),crypto=require('crypto'),assert=require('assert/strict');
const base='bfd4cdeaa5b4abced2c7de2a847f218f57a435b9',dir='docs/ssw-workspace/agriculture/continuation-20261104a/',ld='docs/ssw-workspace/source-coverage-v2/',lp=ld+'agriculture.json',rp='src/data/agriculture/reader-moisture-checks.json';
const read=p=>JSON.parse(fs.readFileSync(p)),old=p=>cp.execFileSync('git',['show',base+':'+p],{maxBuffer:30000000}),hash=v=>crypto.createHash('sha256').update(JSON.stringify(v)).digest('hex'),bytes=b=>crypto.createHash('sha256').update(b).digest('hex'),write=(p,v)=>fs.writeFileSync(p,JSON.stringify(v,null,2)+'\n');
const paths=[lp,rp,...['AGR-S1','AGR-S2'].map(s=>ld+'agriculture-'+s+'-regions.json.gz')];for(const p of paths)assert(fs.readFileSync(p).equals(old(p)),'Changed baseline '+p);
const before=JSON.parse(old(lp)),ledger=structuredClone(before),checks=JSON.parse(old(rp)),priorChecks=structuredClone(checks),assign=read(dir+'assignments.json'),changes=[],added=[],seen=new Set();
for(const lane of Object.keys(assign)){
 const packet=read(dir+lane+'/packet.json');
 for(const c of packet.readerAdditions||[]){assert(!checks.checks.some(v=>v.id===c.id),'Duplicate '+c.id);assert.deepEqual(Object.keys(c.translations).sort(),['en','vi','id','zh-CN','zh-TW','hi','bn','ne','my','th','km','tl'].sort());checks.checks.push(c);added.push(c.id);}
 for(const patch of packet.canonicalUpdates){const id=patch.knowledgeId;assert(assign[lane].includes(id),'Not owned '+id);assert(!seen.has(id),'Repeated '+id);seen.add(id);const index=ledger.knowledgeUnits.findIndex(u=>u.knowledgeId===id),u=ledger.knowledgeUnits[index];assert.equal(hash(u),patch.beforeSha256);assert(!['covered_ai','duplicate','excluded'].includes(u.status));const after=structuredClone(patch.after);assert.equal(after.knowledgeId,id);
 for(const e of [...after.teachingEvidence,...after.assessmentEvidence])if(e.checkId){const ci=checks.checks.findIndex(c=>c.id===e.checkId);assert(ci>=0,'Missing check '+e.checkId);const field=e.checkField||e.field;e.path=rp;e.jsonPointer='/checks/'+ci+(field?'/'+field:'');e.sha256=hash(field?checks.checks[ci][field]:checks.checks[ci]);e.sha256Mode='json-value';delete e.checkId;delete e.checkField;delete e.field;}
 ledger.knowledgeUnits[index]=after;changes.push({lane,knowledgeId:id,beforeStatus:u.status,afterStatus:after.status,beforeSha256:hash(u),afterSha256:hash(after)});
 }
}
const changed=new Set(changes.map(c=>c.knowledgeId)),regionWrites=[];
for(const source of ledger.sources){const p=ld+'agriculture-'+source.sourceId+'-regions.json.gz',a=JSON.parse(z.gunzipSync(old(p)));for(const page of a.pages)for(const e of page.elements)e.knowledgeIds=e.knowledgeIds.filter(id=>!changed.has(id));for(const c of changes){const u=ledger.knowledgeUnits.find(v=>v.knowledgeId===c.knowledgeId);for(const r of u.sourceRefs.filter(r=>r.sourceId===source.sourceId)){const page=a.pages.find(p=>p.pdfPage===r.pdfPage);assert(page);for(const id of r.elementIds){const e=page.elements.find(e=>e.elementId===id);assert(e,'Missing region '+id);e.classification='knowledge';e.knowledgeIds=[...new Set([...e.knowledgeIds,u.knowledgeId])];e.reason=null;}const pageRow=ledger.pages.find(p=>p.sourceId===source.sourceId&&p.pdfPage===r.pdfPage);pageRow.regionCensus.status='visually_reviewed';pageRow.regionCensus.visualReviewRef=u.sourceReview.reviewRef;if(pageRow.semanticInventory.status==='pending')pageRow.semanticInventory={status:'partial',reviewRef:u.sourceReview.reviewRef};if(pageRow.disposition==='unclassified')pageRow.disposition='mixed';}}
 const b=z.gzipSync(JSON.stringify(a),{mtime:0});regionWrites.push([p,b]);for(const page of ledger.pages.filter(p=>p.sourceId===source.sourceId))page.regionCensus.sha256=bytes(b);
}
for(const p of ledger.pages)p.knowledgeIds=ledger.knowledgeUnits.filter(u=>u.sourceRefs.some(r=>r.sourceId===p.sourceId&&r.pdfPage===p.pdfPage)).map(u=>u.knowledgeId);
for(const u of before.knowledgeUnits.filter(u=>['covered_ai','duplicate','excluded'].includes(u.status)))assert.deepEqual(ledger.knowledgeUnits.find(v=>v.knowledgeId===u.knowledgeId),u);
for(const c of priorChecks.checks)assert.deepEqual(checks.checks.find(v=>v.id===c.id),c);
for(const [p,b]of regionWrites)fs.writeFileSync(p,b);write(lp,ledger);write(rp,checks);
const result={schemaVersion:1,status:'integrated_pending_validation',baselineCommit:base,changes,newChecks:added,coveredBefore:616,coveredAfter:ledger.knowledgeUnits.filter(u=>u.status==='covered_ai').length,openKnownUnits:ledger.knowledgeUnits.filter(u=>!['covered_ai','duplicate','excluded'].includes(u.status)).length,priorAcceptedUnitsPreserved:true,priorChecksPreserved:true,sourceCoveragePercent:null,wholeSourceKnowledgeCovered:false,crossWorkerSemanticReview:false,domainReviewed:false,nativeReviewed:false,physicalDeviceTested:false,learnerDurationMeasured:false};write(dir+'integration.json',result);console.log(JSON.stringify({changes:changes.length,newChecks:added.length,covered:result.coveredAfter,open:result.openKnownUnits}));
